from decimal import Decimal
from budgeter.errors import ValidationError


def add_goal(store, name: str, target: str, month: str) -> None:
    """Add a savings goal to the store."""
    from budgeter.model import SavingsGoal
    goal = SavingsGoal(name=name, target=target, month=month)
    store.goals.append(goal)


def contribute(store, goal_name: str, amount: str) -> None:
    """Contribute to a savings goal."""
    from budgeter.model import SavingsGoal
    goal = next((g for g in store.goals if g.name == goal_name), None)
    if goal is None:
        raise ValueError(f"no goal named {goal_name}")
    goal.contribute(Decimal(amount))


def goal_report(store, month: str) -> str:
    """Generate a report of savings goals for a month."""
    lines = [f"Savings Goals for {month}"]
    for goal in store.goals:
